"""Freeze a prospective cohort and the already verified 2026-Q3 parameter package."""
from common49 import *

def main():
    OUT.mkdir(exist_ok=True);guard(not (ROOT/'protocol.json').exists(),'Protocol already exists')
    old=old_evidence();created=utc();start=(pd.Timestamp(created.astimezone(TZ).date())+pd.offsets.Week(weekday=4)).strftime('%Y-%m-%d')
    slots=pd.date_range(start,periods=52,freq='W-FRI').strftime('%Y-%m-%d').tolist()
    comps=[dict(history=h,reference_history=ref,method=m,metric=metric) for h,refs in [(Q,[U]),(W,[U,Q]),(I,[U,Q]),(S,[U,Q])] for ref in refs for m in PRIMARY for metric in ['direction_error','brier']]
    guard(len(comps)==42,'Comparison count')
    inherited={str((PROJECT/f'research_v{v}/protocol.json').relative_to(PROJECT)):sha(PROJECT/f'research_v{v}/protocol.json') for v in [6,26,28,36,39,47,48]}
    protocol=dict(version=49,created_utc=iso(created),experiment='Prospective weekly registry with frozen candidate recipes; no retrospective promotion',scope='Operational registry, strict observed-prefix inference, append-only snapshots/predictions/labels, delayed fixed-cohort evaluation. No new model fit or efficacy search in R49.',target='CSI300 sh000300; original provider-native raw OHLCV',histories=HISTORIES,primary_methods=PRIMARY,diagnostic_methods=[METHODS[0]],seeds=SEEDS,signal_slots=slots,signal_rule='Friday with an observed final daily bar. Record only on that same calendar Friday, 18:00 inclusive to23:00 exclusive Asia/Shanghai, after data retrieval. No backfilling; this is stricter than merely before label maturity. Friday without a bar is not replaced by Thursday. Calendar gaps remain explicit; absence of a bar is not automatically called an exchange holiday.',entry_exit='Entry at first observed daily open after signal; exit at first observed daily open after the next observed same-weekday bar. Label maturity also requires 5 future OHLCV bars and original joint OHLC eligibility. Use source bars, never a guessed holiday calendar.',ensemble='Original three-seed pandas Series.mean of probabilities; up iff p>0.5. All methods and seeds present in one immutable prediction event, no candidate-specific omission. Native MSE and unweighted training frequency remain separate diagnostic controls.',inputs='125 observed OHLCV bars, raw log prices/log1p volume standardized within window and fixed25x5 patches; original frozen neural feature clipping/scaling, supervised ray and market/order interactions.',annual_recipe='Original R28 rolling5 calendar years, jointly mature labels, natural20 epochs,3 fixed seeds; original equal-weight pipeline andR47half-life730.5days weighted heads on the same coordinates. Annual cutoff priorDec31; do not optimize candidates from prospective results.',quarter_recipe='Original R39 state-gated quarterly correction on original annual head: prior quarter end, mature weekly52training/13validation with purge; state train>=10 and validation>=5; sum-ridge20, cap0.5,60bisection steps; Brier strictly better beyond original tolerance, direction correct count not worse; exact zero-offset fallback. Annual state boundaries unchanged until annual update.',hybrids='Original U slopes+W intercept, andW slopes+U intercept; R25ordergamma is a slope. No new conditional refit or parameter selection.',parameter_lifecycle='Bootstrap package reuses annual2025-12-31 andquarter2026-06-30 evidence; valid only through2026-09-30. Runtime rejects stale annual or quarterly cutoffs. Future parameter packages must be built and independently verified under these exact inherited recipes before their first signal. R49 does not implement or schedule the future refitting job; its data and resulting package do not yet exist.',inherited_recipe_protocols=inherited,cohort=dict(calendar_fridays=52,first_slot=slots[0],last_slot=slots[-1],descriptive_checkpoints=[13,26,39],primary_review_not_before=(pd.Timestamp(slots[-1])+pd.Timedelta(days=21)).strftime('%Y-%m-%d'),minimum_complete_mature_signals=40,coverage='Show every scheduled Friday, including no timely prediction, invalid OHLC labels, pending labels and complete records. Missing slots are never replaced to chase the minimum. Forty is an operational minimum, not a statistical power guarantee.',no_optional_stopping='No pvalues or automatic model promotion before the single final review. Less than40complete valid paired signals or pending recorded labels at review => insufficient evidence, no primary claim.'),comparisons=comps,inference=dict(block_weeks=8,bootstrap_replicates=10000,seed=20260910,two_sided_centered=True,holm_family=42,missing='Resample circular blocks over the52calendar slots, retain missing slots and compute each resample mean over observed paired losses. Do not compress gaps into adjacent trading weeks.'),timestamp_contract='Local actual UTC clock recorded at archive/commit; source snapshot and model hashes preserved. Hash chaining detects edits relative to retained evidence but is not independent timestamp notarization. No simulation-clock CLI; past snapshots cannot create a prospective prediction.',data_revisions='Public provider raw response preserved; downloaded overlap with frozen historical OHLCV must match exactly. Later label snapshots must match every stored prediction prefix. Revisions stop settlement and require a separately documented data review, never overwrite prior prediction or label.',runtime='Manual CLI; no background service or automatic weekly job installed. State lives in prospective_r49 outside immutable research_v49 delivery.',validation='Offline historical replay is engineering parity only, not a new prospective observation. Rebuild raw inputs, inference and labels; test timing, stale package, duplicate, tamper, pending/invalid labels, all-seed completeness and primary-evaluation gates.',limits='No independent holdout results until future records mature. No trading profit, deployment or economic causal claim. Preserve all previous research and local improvements.')
    save(ROOT/'protocol.json',protocol)
    p48=PROJECT/'research_v48/results';annual='2025-12-31';quarter='2026-06-30'
    uniform=[h for h in read(p48/'uniform_heads.json') if h['cutoff']==annual]
    weighted=[h for h in read(p48/'weighted_heads.json') if h['cutoff']==annual]
    models=[m for m in read(p48/'source_models.json') if m['cutoff']==annual]
    offsets=read(PROJECT/'research_v39/results/correction_heads.json');gate=pd.read_csv(PROJECT/'research_v39/results/gate_decisions.csv')
    threshold=next(t for t in read(PROJECT/'research_v36/results/state_thresholds.json') if t['encoder_cutoff']==annual)
    q=[]
    for method in METHODS:
        for seed in SEEDS:
            for state in STATES:
                h=next(h for h in offsets if h['cutoff']==quarter and h['method']==method and h['seed']==seed and h['family']=='state' and h['component']==state)
                g=gate[gate.cutoff.eq(quarter)&gate.method.eq(method)&gate.family.eq('state')&gate.component.eq(state)].iloc[0]
                q.append(dict(method=method,seed=seed,state=state,raw_offset=h['offset'],accepted=bool(g.accepted),applied_offset=h['offset'] if g.accepted else 0.,gate_reason=g.reason))
    dependencies=[PROJECT/m['project_file'] for m in models]+[PROJECT/h['cache_file'] for h in uniform]
    dependencies += [PROJECT/n for n in inherited]
    dependencies += [p48/n for n in ['uniform_heads.json','weighted_heads.json','heads.json','source_models.json','verification.json']]
    dependencies += [PROJECT/'research_v39/results'/n for n in ['correction_heads.json','gate_decisions.csv','verification.json']]
    dependencies += [PROJECT/'research_v36/results/state_thresholds.json',PROJECT/'research_v28/results/training_scales.json']
    obs=pd.read_csv(PROJECT/'research_v5/results/observation_table.csv',float_precision='round_trip');training=obs[obs.date.ge('2021-01-01')&obs.joint_completed.le(annual)]
    package=dict(package_id='annual2025-12-31_quarter2026-06-30',assembled_utc=iso(utc()),annual_cutoff=annual,quarter_cutoff=quarter,valid_from='2026-07-01',valid_until='2026-09-30',uniform=uniform,weighted=weighted,models=models,quarter_offsets=q,volatility_median=threshold['volatility_median'],return_scale=read(PROJECT/'research_v28/results/training_scales.json')['rolling5_'+annual],training_up_frequency=float((training.exec_return>0).mean()),dependencies={str(p.relative_to(PROJECT)):sha(p) for p in dependencies},provenance='Copy of verified R28/R36/R39/R47/R48 sources. Existing estimates; no new fit.')
    guard(len(uniform)==len(weighted)==12 and len(models)==3 and len(q)==48,'Incomplete package')
    save(OUT/'bootstrap_package.json',package)
    immutable=dict(read(p48/'preparation_manifest.json')['source_sha256'])
    immutable.update(inherited)
    immutable.update(package['dependencies'])
    immutable.update({str(p.relative_to(PROJECT)):sha(p) for p in ROOT.glob('*.py')})
    for n in ['research/data/1_000300.csv','research_v5/results/observation_table.csv','research_v5/cache/packed_raw.npz','research_v4/data.py','research_v4/util.py','research_v3/common.py','research_v39/results/weekly_signal_bank.csv','research_v48/results/model_predictions.csv','research_v48/results/ensemble_predictions.csv']:
        immutable[n]=sha(PROJECT/n)
    immutable[str((OUT/'bootstrap_package.json').relative_to(PROJECT))]=sha(OUT/'bootstrap_package.json')
    save(OUT/'freeze.json',dict(created_utc=iso(utc()),protocol_sha256=sha(ROOT/'protocol.json'),immutable_files=immutable,old_evidence=old,new_fits=0,prospective_records_at_freeze=0))
    Journal().initialize();print(f'R49 frozen: first slot {slots[0]}, last {slots[-1]},42comparisons,6206oldfiles; empty prospective journal.')
if __name__=='__main__':main()
